#!/usr/bin/env python# -*- coding: utf-8 -*-"""Image data structures.This module provides base classes and mixins for images."""from __future__ import annotations__all__ = [    "Image",]import cv2import numpy as npfrom mon.core.pathlib import Pathfrom ..base import PersistentData# ==============================================================================# region CONSTANTS# ==============================================================================_CV2_IMREAD_FLAGS = [    cv2.IMREAD_ANYCOLOR,    cv2.IMREAD_ANYDEPTH,    cv2.IMREAD_COLOR,    cv2.IMREAD_COLOR_BGR,    cv2.IMREAD_COLOR_RGB,    cv2.IMREAD_GRAYSCALE,    cv2.IMREAD_UNCHANGED,]# endregion# ==============================================================================# region TYPE DEFINITIONS & PROTOCOLS# ==============================================================================# --- Type Aliases ---# --- Protocols ---# endregion# ==============================================================================# region BASE CLASSES & MIXINS# ==============================================================================# --- Base Classes ---# --- Mixins ---# endregion# ==============================================================================# region CONCRETE IMPLEMENTATIONS# ==============================================================================class Image(PersistentData):    """Basic class for managing a single image.    Extend ``PersistentData`` to handle image data and provide properties and    methods related to images.    Attributes:        _data (numpy.ndarray | None): RGB or grayscale image, formatted as a            numpy.ndarray of shape (H, W, C) and pixel values ranging from 0 to            255.        _shape (tuple[int, int, int]): Image shape as (H, W, C).        _flags (int): OpenCV flag to read the image.    """    # --- Lifecycle & Initialization ---    def __init__(        self,        data   : np.ndarray | Path | str | None = None,        path   : Path | str | None              = None,        root   : Path | str | None              = None,        flags  : int                            = cv2.IMREAD_COLOR,        persist: bool                           = False,    ):        """Initialize a new instance.        Args:            data: Either an RGB or grayscale image, formatted as a                numpy.ndarray of shape (H, W, C) and pixel values ranging from                0 to 255, or an image file path.            path: Image file path.            root: Root directory of the image (of a dataset).            flags: OpenCV flag to read the image.            persist: If True, persists the loaded image in memory.        Raises:            TypeError: If ``data`` is neither a numpy.ndarray nor a valid image                file path.            FileNotFoundError: If ``data`` is None and ``path`` does not point                to a valid image file.            ValueError: If both ``data`` and ``path`` are None.            ValueError: If ``flags`` is not a valid OpenCV imread flag.        """        # Validate data and infer shape        shape = None        if isinstance(data, (Path, str)):            p = Path(data).normalize()            if p.is_image_file(exist=True):                path = p                data = None        if isinstance(data, np.ndarray):            shape = data.shape        elif data is not None:            raise TypeError(                f"Expected 'data' to be a numpy.ndarray or a valid image file path, "                f"but got {type(data).__name__}."            )        # Validate paths        path = Path(path).normalize(exist=True) if path else None        root = Path(root).normalize(exist=True) if root else None        if data is None:            if path is not None:                if path.is_image_file(exist=True):                    from . import io                    shape = io.read_shape(path=path)                else:                    raise FileNotFoundError(f"Image file not found at: {path}")            else:                raise ValueError(f"Expected 'data' or a valid image file path, but got both None.")        # Call the setter to ensure type validation on init        self._shape = shape        self.flags  = flags        # Continue the initialization chain        super().__init__(data=data, path=path, root=root, persist=persist)    # --- Representation ---    def __repr__(self) -> str:        """Return the official string representation for developers."""        return f"{self.__class__.__name__}(shape={self.shape}, path={self.path})"    # --- Container / Sequence Methods ---    def __len__(self) -> int:        """Return the length of the container.        For an image, this is always 1.        """        return 1    def __getitem__(self, index: int = 0) -> np.ndarray:        """Return the image data.        Args:            index: Index to access.        """        return self.data    # --- Properties ---    @property    def shape(self) -> tuple[int, int, int]:        """Return the image shape as (H, W, C)."""        return self._shape    @property    def imgsz(self) -> tuple[int, int]:        """Return the image size as (H, W)."""        return self.shape[0], self.shape[1]    @property    def flags(self) -> int:        """Return the OpenCV flag used to read the image."""        return self._flags    @flags.setter    def flags(self, value: int):        """Set the OpenCV flag used to read the image.        Args:            value: OpenCV flag to read the image.        Raises:            ValueError: If the provided ``value`` is not a valid OpenCV imread                flag.        """        if value not in _CV2_IMREAD_FLAGS:            raise ValueError(                f"Unsupported 'flags': {value}. Must be one of: {_CV2_IMREAD_FLAGS}."            )        self._flags = value    @property    def meta(self) -> dict:        """Return metadata describing the data."""        return {            "path" : self.path,            "root" : self.root,            "shape": self.shape,            "imgsz": self.imgsz,            "hash" : self.path.stat().st_size if isinstance(self.path, Path) else None,        }    # --- Data Loading ---    def load(self, reload: bool = False) -> np.ndarray:        """Load an image from disk to memory.        Args:            reload: If True, force reloading even if data is already in memory.                Defaults to False.        Returns:            RGB or grayscale image, formatted as a numpy.ndarray of shape            (H, W, C) and pixel values ranging from 0 to 255.        Raises:            ValueError: If ``path`` is not set.        """        # Return the image if it is already loaded        if self._data is not None and not reload:            return self._data        if self.path is None:            raise ValueError(f"Expected 'path' to be defined, but got {self.path}.")        # Load the image from the disk        from . import io        image = io.read(self.path, self._flags)        # Update the original shape of the image        if self._shape != image.shape:            self._shape = image.shape        # Cache the image if needed        if self._persist:            self._data = image        else:            self.clear()        return image# endregion# ==============================================================================# region UNIT TEST# ==============================================================================if __name__ == "__main__":    pass# endregion